create sequence public.leads_short_id_seq;
create sequence public.audit_log_id_seq;
create table public.accounts_registry (id uuid not null default gen_random_uuid(), service text not null, purpose text, venture_id uuid, login_email text, vault_ref text, created_by text not null default 'moe'::text, verified boolean not null default false, status text not null default 'active'::text, notes text, created_at timestamp with time zone not null default now());
create table public.agent_runs (id uuid not null default gen_random_uuid(), agent_id uuid not null, started_at timestamp with time zone not null default now(), finished_at timestamp with time zone, status text not null default 'running'::text, cost_cents integer not null default 0, summary text);
create table public.agents (id uuid not null default gen_random_uuid(), slug text not null, title text not null, venture_id uuid, charter text, metric text, daily_spend_cap_cents integer not null default 50, status text not null default 'active'::text, prompt_version integer not null default 1, created_at timestamp with time zone not null default now(), department_slug text, role text not null default 'specialist'::text, model_tier text not null default 'cheap'::text, can_contact_owner boolean not null default false);
create table public.audit_log (id bigint not null default nextval('audit_log_id_seq'), at timestamp with time zone not null default now(), actor text not null, action text not null, target text, detail jsonb);
create table public.build_requests (id uuid not null default gen_random_uuid(), requested_by text not null, title text not null, spec text not null, risk text not null default 'low'::text, touches_money_or_messages boolean not null default false, status text not null default 'proposed'::text, approved_by text, qa_agent text, test_result text, rollback_plan text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create table public.company_profile (venture_slug text not null, sender_name text, brand text, mailing_address text, reply_email text, updated_at timestamp with time zone not null default now());
create table public.dayjob_days (day date not null, dials integer not null default 0, pitches integer not null default 0, submissions integer not null default 0, paid_deals integer not null default 0, updated_at timestamp with time zone not null default now());
create table public.dayjob_targets (id integer not null default 1, dials_per_day integer not null default 250, pitches_per_day integer not null default 6, submissions_per_day integer not null default 2, paid_deals_per_week integer not null default 5, payout_cents_per_deal integer not null default 100000);
create table public.deals (id uuid not null default gen_random_uuid(), venture_id uuid not null, lead_id uuid, stage text not null default 'pitched'::text, value_cents integer, notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create table public.departments (slug text not null, name text not null, venture_id uuid, kind text not null default 'venture'::text, status text not null default 'active'::text);
create table public.escalations (id uuid not null default gen_random_uuid(), from_agent text not null, department_slug text, kind text not null, summary text not null, evidence jsonb, status text not null default 'open'::text, resolution text, created_at timestamp with time zone not null default now(), resolved_at timestamp with time zone);
create table public.handbook (id uuid not null default gen_random_uuid(), version integer not null, content text not null, active boolean not null default false, created_at timestamp with time zone not null default now());
create table public.human_handoffs (id uuid not null default gen_random_uuid(), requested_by text not null, task text not null, why_human text not null, url text, status text not null default 'open'::text, created_at timestamp with time zone not null default now(), completed_at timestamp with time zone);
create table public.ideas (id uuid not null default gen_random_uuid(), name text not null, description text, speed_to_cash integer, startup_cost_cents integer, effort integer, status text not null default 'new'::text, test_budget_cents integer, result text, created_at timestamp with time zone not null default now(), revisit_trigger text, verdict text, demand_source text, kill_metric text, test_started_on date, test_ends_on date, score numeric);
create table public.leads (id uuid not null default gen_random_uuid(), venture_id uuid not null, name text, phone text, email text, source text, score integer, status text not null default 'new'::text, consent_basis text, do_not_contact boolean not null default false, notes text, created_at timestamp with time zone not null default now(), next_followup_at date, last_contact_at timestamp with time zone, contact_count integer not null default 0, short_id integer not null default nextval('leads_short_id_seq'::regclass));
create table public.ledger (id uuid not null default gen_random_uuid(), venture_id uuid, kind text not null, amount_cents integer not null, currency text not null default 'CAD'::text, note text, occurred_on date not null default CURRENT_DATE, created_at timestamp with time zone not null default now(), status text not null default 'received'::text, intercompany boolean not null default false, original_currency text, original_amount_cents integer, fx_rate numeric);
create table public.llm_calls (id uuid not null default gen_random_uuid(), agent_slug text not null, model text, purpose text, reserved_cents integer not null, actual_cents integer, status text not null default 'reserved'::text, started_at timestamp with time zone not null default now(), finished_at timestamp with time zone);
create table public.memory (id uuid not null default gen_random_uuid(), venture_id uuid, agent text, kind text not null, content text not null, created_at timestamp with time zone not null default now(), source text, confidence text not null default 'unverified'::text, verified_at timestamp with time zone, expires_at timestamp with time zone);
create table public.missions (id uuid not null default gen_random_uuid(), venture_id uuid, title text not null, objective text not null, success_definition text, status text not null default 'captured'::text, priority integer not null default 3, budget_cents integer not null default 200, expected_cad numeric, days_to_cash integer, verdict text, verdict_reason text, plan jsonb not null default '[]'::jsonb, next_step integer not null default 0, risks text, next_action text, owner_decision text, evidence jsonb not null default '[]'::jsonb, result text, attempts integer not null default 0, checkpoint jsonb not null default '{}'::jsonb, created_by text not null default 'owner'::text, last_progress_at timestamp with time zone not null default now(), created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), completed_at timestamp with time zone);
create table public.model_prices (model text not null, tier text not null, input_usd_per_mtok numeric not null, output_usd_per_mtok numeric not null, long_input_usd_per_mtok numeric, long_output_usd_per_mtok numeric, long_threshold_tokens integer, source text not null, as_of date not null, verified boolean not null default false);
create table public.outbox (id uuid not null default gen_random_uuid(), venture_id uuid, agent text, channel text not null, to_ref text, body text not null, status text not null default 'draft'::text, needs_owner boolean not null default false, created_at timestamp with time zone not null default now(), decided_at timestamp with time zone, lead_id uuid, idempotency_key text, qa_agent text, qa_notes text, sources jsonb, sent_at timestamp with time zone);
create table public.owner_messages (id uuid not null default gen_random_uuid(), from_agent text not null, kind text not null, channel text not null default 'telegram'::text, body text not null, created_at timestamp with time zone not null default now(), sent_at timestamp with time zone, needs_decision boolean not null default false, ref_table text, ref_id uuid, decision text, decided_at timestamp with time zone, deliver_after timestamp with time zone, options jsonb, answer text);
create table public.predictions (id uuid not null default gen_random_uuid(), agent_slug text not null, action_ref text, expected text not null, confidence numeric not null, outcome text, correct boolean, created_at timestamp with time zone not null default now(), resolved_at timestamp with time zone);
create table public.reconciliation_flags (id uuid not null default gen_random_uuid(), check_name text not null, detail text not null, status text not null default 'open'::text, created_at timestamp with time zone not null default now());
create table public.system_state (id integer not null default 1, kill_switch boolean not null default false, daily_spend_cap_cents integer not null default 300, mode text not null default 'dry_run'::text, last_heartbeat timestamp with time zone, usd_to_cad numeric not null default 1.45, usd_to_cad_verified boolean not null default false, pause_reason text, paused_at timestamp with time zone, night_until timestamp with time zone, night_started_at timestamp with time zone, day_cap_cents integer);
create table public.systems (slug text not null, venture_slug text, name text not null, url text, health_url text, repo text, data_store text, host text, warmup_local_times text[] default '{}'::text[], notes text, last_status integer, last_ms integer, last_checked_at timestamp with time zone, active boolean not null default true);
create table public.tasks (id uuid not null default gen_random_uuid(), venture_id uuid, assigned_agent text, created_by text, title text not null, detail text, status text not null default 'todo'::text, priority integer not null default 3, due_at timestamp with time zone, result text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), mission_id uuid);
create table public.tool_registry (slug text not null, kind text not null, purpose text not null, owner_agent text, venture_id uuid, monthly_cost_cents integer not null default 0, currency text not null default 'CAD'::text, status text not null default 'active'::text, last_used_at timestamp with time zone, review_by date, notes text);
create table public.ventures (id uuid not null default gen_random_uuid(), slug text not null, name text not null, kind text not null, status text not null default 'active'::text, primary_metric text, gate_criteria text, gate_met boolean not null default false, created_at timestamp with time zone not null default now());
